fn solve(s: Vec<char>) -> Vec<char> {
    // Create a new vector with a capacity of 20
    let mut result = Vec::with_capacity(20);
    
    // Iterate through the input vector
    for &ch in &s {
        if ch == ',' {
            result.push(' '); // Replace comma with space
        } else {
            result.push(ch); // Keep the character as is
        }
    }
    
    // Append the newline character at the end
    result.push('\n');
    
    result // Return the resulting vector
}